const REQUIRED = ['Subject', 'Summary', 'People in meetings', 'Bolet Points', 'Tags'];
const trigger = $('When Executed by Another Workflow').first().json || {};
const MODEL = String(trigger.modelId || '').trim();

function messageText(message) {
  if (!message) return '';
  const content = message.content;
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content.map((part) => {
      if (typeof part === 'string') return part;
      if (part && typeof part.text === 'string') return part.text;
      return '';
    }).join('');
  }
  return '';
}

function parseAnalysis(text) {
  let source = String(text || '').trim();
  if (!source) return null;
  const fenced = source.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) source = fenced[1].trim();
  const tryParse = (value) => {
    try { return JSON.parse(value); } catch (e) { return null; }
  };
  let parsed = tryParse(source);
  if (!parsed) {
    const start = source.indexOf('{');
    const end = source.lastIndexOf('}');
    if (start >= 0 && end > start) parsed = tryParse(source.slice(start, end + 1));
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  if (REQUIRED.some((key) => !Object.prototype.hasOwnProperty.call(parsed, key))) return null;
  return parsed;
}

const item = $input.first().json || {};
if (item.error) {
  const message = (item.error && (item.error.message || item.error.description)) || 'Model request failed';
  throw new Error(message);
}
if (!MODEL) {
  throw new Error('OpenRouter modelId is required');
}
const message = item.choices && item.choices[0] && item.choices[0].message;
const parsed = parseAnalysis(messageText(message));
if (!parsed) {
  throw new Error('Model returned invalid analysis JSON');
}
return [{
  json: {
    candidates: [{ content: { parts: [{ text: JSON.stringify(parsed) }] } }],
    analyzeProvider: 'openrouter',
    analyzeModel: MODEL,
  },
}];

const response = $input.first().json;
const text = response && response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts && response.candidates[0].content.parts[0] && response.candidates[0].content.parts[0].text;
if (!text || !String(text).trim()) {
  throw new Error('OpenRouter analyze returned an empty response');
}
return [{ json: response }];
